ALTER TABLE "app"."workspaces" DROP CONSTRAINT "workspaces_logo_valid";--> statement-breakpoint
ALTER TABLE "app"."projects" ADD COLUMN "accent" text;--> statement-breakpoint
ALTER TABLE "app"."projects" ADD CONSTRAINT "projects_accent_valid" CHECK ("app"."projects"."accent" is null or "app"."projects"."accent" in ('violet', 'blue', 'green', 'amber', 'cyan', 'pink'));--> statement-breakpoint
ALTER TABLE "app"."workspaces" ADD CONSTRAINT "workspaces_logo_valid" CHECK (("app"."workspaces"."logo_kind" in ('monogram', 'home', 'box') and "app"."workspaces"."logo_value" is null) or ("app"."workspaces"."logo_kind" = 'emoji' and length("app"."workspaces"."logo_value") between 1 and 16) or ("app"."workspaces"."logo_kind" = 'icon' and "app"."workspaces"."logo_value" ~ '^[a-z][a-z0-9-]{0,31}$') or ("app"."workspaces"."logo_kind" = 'image' and length("app"."workspaces"."logo_value") <= 49152 and "app"."workspaces"."logo_value" ~ '^data:image/(webp|png)\x3bbase64,[A-Za-z0-9+/]+={0,2}$'));